CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin

  insert into public.profiles (
    id,
    first_name,
    last_name,
    photo_path
  )
  values (
    new.id,
    coalesce(
      nullif(trim(new.raw_user_meta_data ->> 'first_name'), ''),
      'Unknown'
    ),
    coalesce(
      nullif(trim(new.raw_user_meta_data ->> 'last_name'), ''),
      'Unknown'
    ),
    nullif(trim(new.raw_user_meta_data ->> 'photo_path'), '')
  );

  insert into public.user_private (
    user_id,
    phone
  )
  values (
    new.id,
    nullif(trim(new.raw_user_meta_data ->> 'phone'), '')
  );

  insert into public.user_roles (
    user_id,
    role
  )
  values (
    new.id,
    'user'::public.app_role
  );

  insert into public.user_settings (
    user_id
  )
  values (
    new.id
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_week3_conversation(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_has_member boolean;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  -- ถ้ามี conversation นี้อยู่แล้ว
  if exists (
    select 1
    from public.conversations
    where id = p_conversation_id
  ) then

    -- ถ้าผู้ใช้เป็นสมาชิกอยู่แล้ว จบได้เลย
    if exists (
      select 1
      from public.conversation_members
      where conversation_id = p_conversation_id
        and user_id = v_user_id
    ) then
      return;
    end if;

    -- ป้องกันการเข้า conversation ของคนอื่น
    select exists (
      select 1
      from public.conversation_members
      where conversation_id = p_conversation_id
    )
    into v_has_member;

    if v_has_member then
      raise exception 'Conversation already belongs to another user';
    end if;

  else

    -- จุดที่แก้:
    -- created_by ห้ามเป็น NULL
    insert into public.conversations (
      id,
      created_by
    )
    values (
      p_conversation_id,
      v_user_id
    );

  end if;

  -- เพิ่มผู้ใช้ปัจจุบันเป็นสมาชิก
  insert into public.conversation_members (
    conversation_id,
    user_id
  )
  values (
    p_conversation_id,
    v_user_id
  )
  on conflict do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_get_or_create_direct(p_other_user uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_me uuid := auth.uid();
  v_key text;
  v_conversation uuid;
begin
  if v_me is null then
    raise exception 'Authentication required';
  end if;

  if p_other_user is null or p_other_user = v_me then
    raise exception 'Invalid chat recipient';
  end if;

  if not exists (select 1 from public.profiles where id = p_other_user) then
    raise exception 'Recipient not found';
  end if;

  v_key := case
    when v_me::text < p_other_user::text
      then v_me::text || ':' || p_other_user::text
    else p_other_user::text || ':' || v_me::text
  end;

  insert into public.conversations (
    id,
    created_by,
    kind,
    direct_key,
    created_at,
    updated_at
  )
  values (
    gen_random_uuid(),
    v_me,
    'direct',
    v_key,
    now(),
    now()
  )
  on conflict (direct_key) where direct_key is not null
  do update set updated_at = public.conversations.updated_at
  returning id into v_conversation;

  insert into public.conversation_members (conversation_id, user_id, joined_at)
  values
    (v_conversation, v_me, now()),
    (v_conversation, p_other_user, now())
  on conflict do nothing;

  return v_conversation;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_mark_read(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  update public.conversation_members
  set last_read_at = now()
  where conversation_id = p_conversation_id
    and user_id = auth.uid();

  if not found then
    raise exception 'Not a member of this conversation';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_refresh_conversation_preview()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation uuid;
  v_preview text;
  v_time timestamptz;
begin
  if tg_op = 'DELETE' then
    v_conversation := old.conversation_id;
  else
    v_conversation := new.conversation_id;
  end if;
  select
    case m.type
      when 'image' then '📷 รูปภาพ'
      when 'video' then '🎬 วิดีโอ'
      when 'audio' then '🎵 ไฟล์เสียง'
      when 'file' then '📎 ไฟล์'
      when 'location' then '📍 ตำแหน่ง'
      else left(coalesce(m.content, ''), 180)
    end,
    m.created_at
  into v_preview, v_time
  from public.messages m
  where m.conversation_id = v_conversation
    and coalesce(m.is_deleted, false) = false
  order by m.created_at desc
  limit 1;

  update public.conversations
  set last_message_preview = v_preview,
      last_message_at = v_time,
      updated_at = now()
  where id = v_conversation;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$
